export class LabelsPanel extends Component {
  static className = 'labelspanel';
  static propTypes = {
    studies: PropTypes.array.isRequired,
    isStudyLoaded: PropTypes.bool.isRequired,
    diagnoseLabels: PropTypes.array,
    filterValues: PropTypes.object,
    clearCache: PropTypes.func,
  };

  state = {
    checked: (typeof diagnoseLabels === 'undefined' || diagnoseLabels == null) ? ['/normal'] : diagnoseLabels,
    expanded: [],
    clicked: {},
    filterText: '',
    nodesFiltered: nodes,
    nodes,
  };

  constructor(props) {
    super(props);

    this.onCheck = this.onCheck.bind(this);
    this.onClick = this.onClick.bind(this);
    this.onExpand = this.onExpand.bind(this);
    this.onFilterChange = this.onFilterChange.bind(this);
    this.filterTree = this.filterTree.bind(this);
    this.filterNodes = this.filterNodes.bind(this);
  }

  componentDidUpdate(prevProps) {
    const { isStudyLoaded, studies } = this.props;

    if (isStudyLoaded && isStudyLoaded !== prevProps.isStudyLoaded) {
      const checkedNodes = studies[0] ? studies[0].DiagnoseLabels : [];
      this.setState({ checked: this.state.checked.concat(checkedNodes) });
    }
  }

  onCheck(checked) {
    this.setState({ checked });
  }

  onClick(clicked) {
    this.setState({ clicked });
  }

  onExpand(expanded) {
    this.setState({ expanded });
  }

  onFilterChange(e) {
    this.setState({ filterText: e.target.value }, this.filterTree);
  }

  filterTree() {
    // Reset nodes back to unfiltered state
    if (!this.state.filterText) {
      this.setState(prevState => ({
        nodesFiltered: prevState.nodes,
      }));

      return;
    }

    const nodesFiltered = prevState => ({
      nodesFiltered: prevState.nodes.reduce(this.filterNodes, []),
    });

    this.setState(nodesFiltered);
  }

  filterNodes(filtered, node) {
    const { filterText } = this.state;
    const children = (node.children || []).reduce(this.filterNodes, []);

    if (
      // Node's label matches the search string
      node.label.toLocaleLowerCase().indexOf(filterText.toLocaleLowerCase()) >
        -1 ||
      // Or a children has a matching node
      children.length
    ) {
      filtered.push({ ...node, children });
    }

    return filtered;
  }

  onAcceptSave = async () => {
    let display_serie;
    try {
      display_serie = this.props.studies[0].displaySets[0];
    } catch (error) {
      this.handlePostError(
        error,
        'Guardar etiquetas',
        'No es posible identificar la serie.'
      );
      return;
    }
    const postData = {
      checkedLabels: this.state.checked,
      studyInstanceUID: display_serie.StudyInstanceUID,
      seriesInstanceUID: display_serie.SeriesInstanceUID,
      sopInstanceUID: display_serie.SOPInstanceUID,
    };
    fetch('/labels', {
      method: 'post',
      headers: {
        'Content-Type': 'application/json',
        'x-access-token': 'token-value',
      },
      body: JSON.stringify(postData),
    })
      .then(response =>
        this.handlePostResponse(response, 'Etiquetas guardadas.')
      )
      .catch(error => this.handlePostError(error, 'Guardar etiquetas'));
  };
  handlePostResponse = async (response, msg) => {
    const data = response;
    // check for error response
    if (!response.ok) {
      // get error message from body or default to response statusText
      const error = (data && data.message) || response.statusText;
      return Promise.reject(error);
    }

    // clean cache and leave last 10
    this.props.clearCache();

    window.history.replaceState({ dialog: msg, filterValues: this.props.filterValues }, '', '/');
    window.location.replace('/');
  };
  handlePostError = async (
    error,
    title,
    msg = 'La petición no ha podido ser procesada.\nContacte con el grupo RELIANCE por favor.'
  ) => {
    const { UINotificationService, LoggerService } = servicesManager.services;
    if (UINotificationService) {
      UINotificationService.show({
        autoClose: true,
        title: title,
        message: msg,
        type: 'error',
      });
    }
    const message = 'There was an error!' + error;
    LoggerService.error({ message });
  };
  handleFormSubmit = async formSubmitEvent => {
    await formSubmitEvent.preventDefault();

    const { UIModalService } = servicesManager.services;
    if (UIModalService) {
      const ConfirmationSavePanel = ConfirmationPanel;
      const WrappedConfirmationSavePanel = function({ onAccept, onCancel }) {
        const body = (
          <div className="confirmation-body">
            <p>¿Quieres guardar las etiquetas?</p>
          </div>
        );
        return (
          <ConfirmationSavePanel
            body={body}
            onAccept={onAccept}
            onCancel={onCancel}
          />
        );
      };
      UIModalService.show({
        content: WrappedConfirmationSavePanel,
        title: 'Confirmación',
        contentProps: {
          onAccept: this.onAcceptSave,
          onCancel: UIModalService.hide,
        },
      });
    }
  };

  onAcceptDiscard = async () => {
    let display_serie;
    try {
      display_serie = this.props.studies[0].displaySets[0];
    } catch (error) {
      this.handlePostError(
        error,
        'Descartar estudio',
        'No es posible identificar la serie.'
      );
      return;
    }
    const postData = {
      studyInstanceUID: display_serie.StudyInstanceUID,
      seriesInstanceUID: display_serie.SeriesInstanceUID,
      sopInstanceUID: display_serie.SOPInstanceUID,
    };
    fetch('/discard', {
      method: 'post',
      headers: {
        'Content-Type': 'application/json',
        'x-access-token': 'token-value',
      },
      body: JSON.stringify(postData),
    })
      .then(response =>
        this.handlePostResponse(response, 'Estudio descartado.')
      )
      .catch(error => this.handlePostError(error, 'Descartar estudio'));
  };

  handleDiscard = async () => {
    const { UIModalService } = servicesManager.services;
    if (UIModalService) {
      const ConfirmationDiscardPanel = ConfirmationPanel;
      const WrappedConfirmationDiscardPanel = function({ onAccept, onCancel }) {
        const body = (
          <div className="confirmation-body">
            <p>
              ¿Quieres descartar el estudio? Los estudios descartados no podrán
              volver a visualizarse.
            </p>
            <p>Estas son algunas de las razones para descartar un estudio:</p>
            <ul>
              <li>La imagen no es un tórax.</li>
              <li>
                La proyección no es anteroposterior (AP) o posteroanterior (PA).
              </li>
              <li>La imagen es pediátrica.</li>
              <li>
                La imagen no es nítida o no está bien tomada y no se pueden
                identificar las patologías.
              </li>
            </ul>
          </div>
        );
        return (
          <ConfirmationDiscardPanel
            body={body}
            onAccept={onAccept}
            onCancel={onCancel}
          />
        );
      };
      UIModalService.show({
        content: WrappedConfirmationDiscardPanel,
        title: 'Confirmación',
        contentProps: {
          onAccept: this.onAcceptDiscard,
          onCancel: UIModalService.hide,
        },
      });
    }
  };

  render() {
    const { checked, expanded, filterText, nodesFiltered } = this.state;

    return this.props.isStudyLoaded ? (
      <div className="wrapper-labels">
        <form className="labelspanel" onSubmit={this.handleFormSubmit}>
          <input
            className="filter-text"
            placeholder="Buscar..."
            type="text"
            value={filterText}
            onChange={this.onFilterChange}
          />
          <CheckboxTree
            checked={checked}
            expanded={expanded}
            iconsClass="fa4"
            icons={icons}
            nodes={nodesFiltered}
            exclusiveNodes={exclusiveNodes}
            extraConnections={extraConnections}
            expandOnClick
            showExpandAll
            onCheck={this.onCheck}
            onClick={this.onClick}
            onExpand={this.onExpand}
            showNodeIcon={false}
          />
          <button id="save-labels" className="btn btn-default" type="submit">
            Guardar
          </button>
        </form>
        <div className="wrapper-button">
          <button
            id="dismiss-study"
            className="btn btn-default"
            onClick={this.handleDiscard}
          >
            Descartar
          </button>
        </div>
      </div>
    ) : (
      <h3>Loading...</h3>
    );
  }
}

export default LabelsPanel;
