import React, { Component } from 'react';
import PropTypes from 'prop-types';
import './ConfirmationPanel.css';

export class ConfirmationPanel extends Component {
  static className = 'confirmationpanel';
  propTypes = {
    body: PropTypes.object.isRequired,
    onAccept: PropTypes.func,
    onCancel: PropTypes.func,
  };
  state = {};

  constructor(props) {
    super(props);

    this.onAccept = props.onAccept;
    this.onCancel = props.onCancel;
    this.body = props.body;
  }
  onAcceptDefault = () => {
    if (
      document
        .getElementById('accept-labels')
        .classList.contains('is-submitting')
    )
      return false;
    document.getElementById('accept-labels').classList.add('is-submitting');

    this.onAccept();
    document.getElementById('accept-labels').classList.remove('is-submitting');
  };

  render() {
    return (
      <div className="buttons-div">
        {this.body}
        <button
          id="accept-labels"
          className="btn btn-default"
          onClick={this.onAcceptDefault}
        >
          Aceptar
        </button>
        <button
          id="cancel-labels"
          className="btn btn-default"
          onClick={this.onCancel}
        >
          Cancelar
        </button>
      </div>
    );
  }
}

export default ConfirmationPanel;
